gLw(){return"\u0646\u0645\u0648\u0648\u0646\u06d5:"},
gLo(){return"\u0632\u0645\u0627\u0646"},
gLq(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0645\u0646"},
gCS(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0626\u06ce\u0633\u062a\u0627"},
gLr(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644\u06cc \u0646\u0648\u06ce"},
gLt(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
